	/** Places the MINUS where a correlated caller can reach it: the optional part of an OPTIONAL. */
	private static Difference correlated(Difference difference) {
		new LeftJoin(pattern("s", "p", "z"), difference);
		return difference;
	}

	private static List<BindingSet> evaluate(MinusQueryEvaluationStep step, BindingSet bindings) {
		List<BindingSet> results = new ArrayList<>();
		try (CloseableIteration<BindingSet> iteration = step.evaluate(bindings)) {
			while (iteration.hasNext()) {
				results.add(iteration.next());
			}
		}
		return results;
	}

	/** Rows compatible with (and extended by) the supplied input bindings, mimicking a statement pattern. */
	private static CloseableIteration<BindingSet> matching(BindingSet bindings, BindingSet... candidates) {
		List<BindingSet> compatible = new ArrayList<>();
		for (BindingSet candidate : candidates) {
			if (bindings.isCompatible(candidate)) {
				QueryBindingSet merged = new QueryBindingSet(bindings);
				merged.addAll(candidate);
				compatible.add(merged);
			}
		}
		return new CloseableIteratorIteration<>(compatible.iterator());
	}

	private static CloseableIteration<BindingSet> rows(BindingSet... rows) {
		return new CloseableIteratorIteration<>(List.of(rows).iterator());
	}

	private static BindingSet row(String name, Value value) {
		QueryBindingSet row = new QueryBindingSet(1);
		row.addBinding(name, value);
		return row;
	}

	private static BindingSet extend(BindingSet bindings, String name, Value value) {
		QueryBindingSet row = new QueryBindingSet(bindings);
		row.addBinding(name, value);
		return row;
	}

	private static StatementPattern pattern(String subject, String predicate, String object) {
		return new StatementPattern(new Var(subject), new Var("_const_" + predicate, VF.createIRI("urn:" + predicate)),
				new Var(object));
	}
